const item = $input.first();
let finalData = {};

// 1. STRICT CHECK: Check karo ki 'data' naam ka binary object exist karta hai ya nahi
if (item.binary && item.binary.data) {
  // Scenario A: Data binary file me aaya hai
  const binaryDataBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  const jsonString = binaryDataBuffer.toString('utf-8');
  finalData = JSON.parse(jsonString);
} 
// 2. Agar binary nahi hai, toh check karo ki standard body aayi hai kya
else if (item.json && item.json.body) {
  // Scenario B: Data normally JSON body me aaya hai
  finalData = item.json.body;
} 
// 3. Failsafe (Agar dono hi format nahi mile)
else {
  finalData = item.json; 
}

// 4. Saari binary fields collect karo (agar koi 'data' ke alawa images wagerah aayi hain)
const allBinaries = {};
if (item.binary) {
  for (const key of Object.keys(item.binary)) {
    if (key !== 'data') {
      allBinaries[key] = item.binary[key];
    }
  }
}

// 5. Final item construct karo
const outputItem = {
  json: {
    ...finalData
  }
};

// Binary object sirf tabhi attach karo jab actually koi aur image bachi ho
if (Object.keys(allBinaries).length > 0) {
  outputItem.binary = allBinaries;
}

return [outputItem];

const item = $input.first().json;

return [
  {
    json: {
      type: item.type,
      message: item.message,
      sosLat: Number(item.lat),
      sosLng: Number(item.lng),
      videoUrl: item.videoUrl
    }
  }
];

const items = $input.all();

function getDistance(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) *
    Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

const nearby = items.filter(item => {
  const d = item.json;

  const distance = getDistance(
    d.sosLat,
    d.sosLng,
    d.userLat,
    d.userLng
  );

  return distance <= 5;
});

return nearby.map(i => ({ json: i.json }));

const docs = $input.first().json.documents;

const users = docs.map(doc => {
  const fields = doc.fields;

  return {
    name: fields.name.stringValue,
    userLat: fields.lat.doubleValue,
    userLng: fields.lng.doubleValue,
    fcmToken: fields.fcmToken.stringValue,

  };
});

return users.map(user => ({ json: user }));

